"""Generated by OpenAI Codex on 2026-11-03. Pedestrian connectivity and ranking."""

import pytest
from services.navigation import name_rank, route


def network():
    objects = {
        str(i): {
            "id": str(i),
            "type": "node",
            "tags": {},
            "position": [43, -84 + i / 10000],
            "refs": [],
        }
        for i in range(5)
    }
    objects["path"] = {
        "id": "path",
        "type": "way",
        "tags": {"highway": "footway"},
        "refs": [{"id": str(i)} for i in range(4)],
    }
    return objects


def test_closest_names_first():
    names = ["East Administrative Building", "Northeast", "East Hall", "East", "Eats"]
    assert sorted(names, key=lambda name: name_rank("east", name))[:3] == [
        "East",
        "East Hall",
        "East Administrative Building",
    ]
    assert name_rank(" East ", "EAST")[0] == 0


def test_route_geometry_and_distance():
    result = route(network(), "0", "3")
    assert len(result["geometry"]["coordinates"]) == 4
    assert 20 < result["properties"]["distance_m"] < 30
    assert result["properties"]["steps"][0]["feature_id"] == "path"


def test_building_uses_connected_entrance():
    objects = network()
    objects["building"] = {
        "id": "building",
        "type": "way",
        "tags": {"building": "yes"},
        "refs": [],
    }
    for key in ["3", "4"]:
        objects[key].update(building_id="building", tags={"entrance": "main"})
    assert route(objects, "0", "building")["properties"]["destination_node"] == "3"


@pytest.mark.parametrize(
    "tags",
    [{"access": "private"}, {"foot": "no"}, {"foot:conditional": "yes @ (Mo-Fr)"}],
)
def test_excludes_restricted_paths(tags):
    objects = network()
    objects["path"]["tags"].update(tags)
    with pytest.raises(ValueError, match="no connected"):
        route(objects, "0", "3")


def test_missing_node_does_not_create_shortcut():
    objects = network()
    del objects["1"]
    with pytest.raises(ValueError):
        route(objects, "0", "3")


def test_oneway_foot_and_stairs():
    objects = network()
    objects["path"]["tags"].update({"oneway:foot": "yes", "highway": "steps"})
    assert route(objects, "0", "3")["properties"]["has_stairs"]
    with pytest.raises(ValueError, match="No connected walking route"):
        route(objects, "3", "0")


def test_overlapping_coordinates_do_not_imply_connection():
    objects = network()
    objects["4"]["position"] = objects["3"]["position"]
    with pytest.raises(ValueError):
        route(objects, "0", "4")


def test_shortest_path_wins():
    objects = network()
    objects["1"]["position"] = [44, -84]
    objects["shortcut"] = {
        "id": "shortcut",
        "type": "way",
        "tags": {"highway": "footway"},
        "refs": [{"id": "0"}, {"id": "3"}],
    }
    assert (
        route(objects, "0", "3")["properties"]["steps"][0]["feature_id"] == "shortcut"
    )
